function withSuspensionStance(config, suspension) {
  const staticBodyOffsetY = suspension.rideHeight - config.body.groundClearance;
  return {
    ...config,
    staticBodyOffsetY,
    collisionDimensions: {
      ...config.collisionDimensions,
      groundClearance: config.body.groundClearance,
      bodyOffsetY: staticBodyOffsetY
    },
    body: {
      ...config.body,
      wheelArchCenterY: config.dimensions.wheelRadius - staticBodyOffsetY,
      wheelArchClearance: Math.max(config.body.wheelArchClearance, suspension.suspensionTravel * 0.5 + 5e-3)
    }
  };
}
